			java.util.Date tDate = dfDate.parse(pDate,
					new java.text.ParsePosition(0));
			java.sql.Timestamp timeStamp = new java.sql.Timestamp(tDate
					.getTime());

			return (java.util.Date) timeStamp;
		} catch (Exception e) {
			try {
